mapper.select:
select l.log_id, l.supplier_id, l.hospital_id, l.certificate_id, l.change_type, l.before_json, l.after_json, l.create_by, l.create_time, s.company_name as supplier_name, s.supplier_code as supplier_code, h.hospital_name as hospital_name, h.hospital_code as hospital_code, c.expire_date as expire_date from scm_supplier_cert_change_log l left join scm_supplier s on l.supplier_id = s.supplier_id left join scm_hospital h on l.hospital_id = h.hospital_id left join scm_supplier_certificate c on l.certificate_id = c.certificate_id
and l.supplier_id = #{supplierId}
and l.hospital_id = #{hospitalId}
and l.certificate_id = #{certificateId}
and l.change_type = #{changeType}
and h.hospital_name like concat('%', #{hospitalName}, '%')
and s.company_name like concat('%', #{supplierName}, '%')
and ( ifnull(l.after_json, '') like concat('%', #{certificateType}, '%') or ifnull(l.before_json, '') like concat('%', #{certificateType}, '%') )
and date(l.create_time) >= date(#{params.beginTime})
and date(l.create_time) <= date(#{params.endTime})
and c.expire_date is not null and date(c.expire_date) <= date_add(curdate(), interval #{params.expireWithinDays} day)
order by c.expire_date asc, l.create_time desc
